with active_customer as (select customer_id, customer_name from customer where status = 'ACTIVE' and created_at >= date '2026-01-01'), order_total as (select customer_id, count(*) order_count, sum(amount) total_amount from order_payoil where deleted = 0 group by customer_id) select ac.customer_id, ac.customer_name, nvl(ot.order_count, 0) order_count, nvl(ot.total_amount, 0) total_amount from active_customer ac left join order_total ot on ot.customer_id = ac.customer_id where nvl(ot.total_amount, 0) >= 0 order by total_amount desc;
